package org.apache.commons.cli;

import static org.junit.jupiter.api.Assertions.*;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

public class AddOptionGroupTests {
    private Options options;
    private OptionGroup requiredGroup;
    private OptionGroup optionalGroup;
    private Option option1;
    private Option option2;
    private Option option3;

    @BeforeEach
    public void setUp() {
        options = new Options();
        option1 = Option.builder("a").longOpt("alpha").build();
        option2 = Option.builder("b").longOpt("beta").build();
        option3 = Option.builder("c").longOpt("gamma").build();
        requiredGroup = new OptionGroup();
        optionalGroup = new OptionGroup();
    }

    @Test
    public void testAddOptionGroupWithRequiredGroup() {
        requiredGroup.addOption(option1);
        requiredGroup.addOption(option2);
        requiredGroup.setRequired(true);

        Options result = options.addOptionGroup(requiredGroup);

        assertSame(options, result);
        assertTrue(requiredGroup.isRequired());
        assertFalse(option1.isRequired());
        assertFalse(option2.isRequired());

        // Check that required group is in requiredOpts
        assertTrue(options.getRequiredOptions().contains(requiredGroup));

        // Check options were added
        assertEquals(2, options.getOptions().size());
        assertNotNull(options.getOption("a"));
        assertNotNull(options.getOption("b"));

        // Check option group mapping
        assertEquals(requiredGroup, options.getOptionGroup(option1));
        assertEquals(requiredGroup, options.getOptionGroup(option2));
    }

    @Test
    public void testAddOptionGroupWithOptionalGroup() {
        optionalGroup.addOption(option1);
        optionalGroup.addOption(option2);
        optionalGroup.setRequired(false);

        Options result = options.addOptionGroup(optionalGroup);

        assertSame(options, result);
        assertFalse(optionalGroup.isRequired());
        assertFalse(option1.isRequired());
        assertFalse(option2.isRequired());

        // Check that optional group is NOT in requiredOpts
        assertFalse(options.getRequiredOptions().contains(optionalGroup));

        // Check options were added
        assertEquals(2, options.getOptions().size());
        assertNotNull(options.getOption("a"));
        assertNotNull(options.getOption("b"));

        // Check option group mapping
        assertEquals(optionalGroup, options.getOptionGroup(option1));
        assertEquals(optionalGroup, options.getOptionGroup(option2));
    }

    @Test
    public void testAddOptionGroupOverwritesRequiredFlagOnOptions() {
        Option requiredOption = Option.builder("r").required(true).build();
        requiredGroup.addOption(requiredOption);
        requiredGroup.setRequired(true);

        options.addOptionGroup(requiredGroup);

        assertFalse(requiredOption.isRequired());

        // Check that group is in requiredOpts
        assertTrue(options.getRequiredOptions().contains(requiredGroup));

        // Check option was added
        assertNotNull(options.getOption("r"));

        // Check option group mapping
        assertEquals(requiredGroup, options.getOptionGroup(requiredOption));
    }

    @Test
    public void testAddOptionGroupRemovesOptionFromRequiredOpts() {
        Option standaloneRequired = Option.builder("s").required(true).build();
        options.addOption(standaloneRequired);

        // Verify option is initially required
        assertTrue(options.getRequiredOptions().contains("s"));

        optionalGroup.addOption(standaloneRequired);
        options.addOptionGroup(optionalGroup);

        assertFalse(standaloneRequired.isRequired());

        // Verify option is no longer in requiredOpts
        assertFalse(options.getRequiredOptions().contains("s"));

        // Check option still exists
        assertNotNull(options.getOption("s"));

        // Check option group mapping
        assertEquals(optionalGroup, options.getOptionGroup(standaloneRequired));
    }

    @Test
    public void testAddMultipleOptionGroups() {
        requiredGroup.addOption(option1);
        requiredGroup.setRequired(true);
        optionalGroup.addOption(option2);
        optionalGroup.setRequired(false);

        options.addOptionGroup(requiredGroup);
        options.addOptionGroup(optionalGroup);

        assertEquals(2, options.getOptions().size());
        assertNotNull(options.getOption("a"));
        assertNotNull(options.getOption("b"));

        // Check required groups
        assertTrue(options.getRequiredOptions().contains(requiredGroup));
        assertFalse(options.getRequiredOptions().contains(optionalGroup));

        // Check option group mappings
        assertEquals(requiredGroup, options.getOptionGroup(option1));
        assertEquals(optionalGroup, options.getOptionGroup(option2));
    }

    @Test
    public void testAddOptionGroupWithEmptyGroup() {
        Options result = options.addOptionGroup(new OptionGroup());

        assertSame(options, result);
        assertEquals(0, options.getOptions().size());
        assertEquals(0, options.getRequiredOptions().size());
    }

    @Test
    public void testAddOptionGroupPreservesExistingOptions() {
        Option existingOption = Option.builder("x").build();
        options.addOption(existingOption);

        optionalGroup.addOption(option1);
        options.addOptionGroup(optionalGroup);

        assertEquals(2, options.getOptions().size());
        assertNotNull(options.getOption("x"));
        assertNotNull(options.getOption("a"));
    }

    @Test
    public void testOptionGroupMappingIsCorrect() {
        optionalGroup.addOption(option1);
        optionalGroup.addOption(option2);
        requiredGroup.addOption(option3);
        requiredGroup.setRequired(true);

        options.addOptionGroup(optionalGroup);
        options.addOptionGroup(requiredGroup);

        // Check all options exist
        assertNotNull(options.getOption("a"));
        assertNotNull(options.getOption("b"));
        assertNotNull(options.getOption("c"));

        // Check option group mappings
        assertEquals(optionalGroup, options.getOptionGroup(option1));
        assertEquals(optionalGroup, options.getOptionGroup(option2));
        assertEquals(requiredGroup, options.getOptionGroup(option3));
    }

    @Test
    public void testChainingAddOptionGroupCalls() {
        OptionGroup group1 = new OptionGroup();
        group1.addOption(option1);
        OptionGroup group2 = new OptionGroup();
        group2.addOption(option2);

        Options result = options.addOptionGroup(group1).addOptionGroup(group2);

        assertSame(options, result);
        assertEquals(2, options.getOptions().size());
        assertNotNull(options.getOption("a"));
        assertNotNull(options.getOption("b"));
        assertEquals(group1, options.getOptionGroup(option1));
        assertEquals(group2, options.getOptionGroup(option2));
    }
